#include <bits/stdc++.h>
using namespace std;

long long count_leq(const vector<int>& x, int limit) {
    if (limit < 0) return 0LL;
    long long ans = 0;
    long long sum = 0;
    int left = 0;
    int n = (int)x.size();

    for (int right = 0; right < n; ++right) {
        sum += x[right];
        while (sum > limit) {
            sum -= x[left];
            ++left;
        }
        ans += (long long)(right - left + 1);
    }

    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    vector<int> x(N);
    for (int i = 0; i < N; ++i) {
        cin >> x[i];
    }

    long long ans = count_leq(x, K) - count_leq(x, K - 1);
    cout << ans << '\n';

    return 0;
}
